// Spreadsheet revision 2026-11-20. Original answers remain available as a legacy export.
const revQuestions=window.REVISION.questions;
const revStages=['你的执业信息','业务方向','想服务的人','一段真实经历','账号与表达'];const coreIds=[['N001','N003','N004','N007'],['N009','N036'],['N043','N045'],['N016'],['N071','N063','N064']];
const revGroups={career:['N014','N015','N016'],cases:['N027','N028','N029','N031','N032','N035'],priority:['N036','N038','N041'],excluded:['N037'],clients:['N043','N044','N045','N046','N046A'],services:['N047','N048','N049','N050']};
const revGroupNames={career:'职业经历',cases:'代表事项',priority:'主推业务',excluded:'不承接业务',clients:'目标客户',services:'收费服务'};
function revInit(){if(state.revision&&state.revision.version!==3){state.previousRevision=structuredClone(state.revision);state.revision=null;}if(!state.revision){state.legacyBackup=structuredClone({answers:state.answers,extra:state.extra});state.revision={version:3,values:{},records:{},step:0};}return state.revision;}
function revOptions(id){return window.REVISION.options.filter(o=>o.question===id&&o.id&&o.id.includes('_O'));}
function revGroup(id){return Object.keys(revGroups).find(g=>revGroups[g].includes(id));}
function revValue(id,record){return record?record.values[id]:revInit().values[id];}
function revText(id,v){if(v===null||v===undefined)return '';if(typeof v!=='object')return String(v);if(Array.isArray(v))return v.map(link=>{const r=revInit();return (r.records.priority||[]).find(x=>x.id===link.business)?.values.N036+' → '+(r.records.services||[]).find(x=>x.id===link.service)?.values.N047}).join('；');if(v.selected)return v.selected.map(k=>revOptions(id).find(o=>o.id===k)?.text||k).join('；')+(v.other?'；'+v.other:'')+(v.note?'；'+v.note:'');if(v.start)return v.start+' 至 '+(v.end||'至今');return '';}
function revFirst(id){const g=revGroup(id);return g?revInit().records[g]?.[0]?.values[id]:revInit().values[id];}
function revLabel(id){return revText(id,revFirst(id));}
function revHas(id){return revLabel(id).trim()!=='';}
function revSocial(){return (revHas('N071')&&!revLabel('N071').includes('尚未开设'))||/抖音|小红书|视频号|公众号|其他内容平台/.test(revLabel('N055'));}
function revVisible(q){const id=q.id;if(['N052','N053'].includes(id))return revHas('N051');if(['N056','N057','N058'].includes(id))return revSocial();if(['N071A','N071B','N072','N073','N074','N075'].includes(id))return revHas('N071')&&!revLabel('N071').includes('尚未开设');if(id==='N059')return revHas('N036')&&revHas('N047');return true;}
function revSync(){const r=revInit();for(const q of revQuestions){if(q.id==='N078')continue;const g=revGroup(q.id);state.extra[q.id]=g?(r.records[g]||[]).map(row=>revText(q.id,row.values[q.id])).filter(Boolean).join('\n'):revText(q.id,r.values[q.id]);}Object.assign(state.answers,{city:revLabel('N003'),years:revLabel('N004'),priority:revLabel('N036'),client:revLabel('N043'),question:revLabel('N045'),excluded:revLabel('N037'),story:revLabel('N016'),goal:'',time:''});state.readinessChecks={};save();}
function revControl(q,record){const id=q.id,v=revValue(id,record),key=record?record.id+'|'+id:id;const attr=`data-rev="${key}"`;const opts=revOptions(id);let input='';
 if(opts.length){const chosen=v?.selected||[];const max=Number(opts[0].max)||opts.length;input=`<div class="choices">${opts.map(o=>`<button type="button" class="choice ${chosen.includes(o.id)?'selected':''}" ${attr} data-opt="${o.id}" aria-pressed="${chosen.includes(o.id)}">${esc(o.text)}</button>`).join('')}</div><small>${q.type.includes('多选')?'最多选择 '+max+' 项；按选择顺序记录优先级':'单选'} · 已选 ${chosen.length} 项</small>`;if(chosen.some(k=>opts.find(o=>o.id===k)?.other==='是'))input+=`<label>其他说明<input ${attr} data-part="other" value="${esc(v?.other||'')}" placeholder="请注明"></label>`;if(q.type.includes('＋'))input+=`<label>具体说明<textarea ${attr} data-part="note">${esc(v?.note||'')}</textarea></label>`;
 }else if(q.type==='关联选择'){const r=revInit();input=(r.records.priority||[]).map(b=>`<fieldset><legend>${esc(revText('N036',b.values.N036))}</legend>${(r.records.services||[]).map(s=>`<label class="relation"><input type="checkbox" ${attr} data-link="${b.id}|${s.id}" ${(v||[]).some(l=>l.business===b.id&&l.service===s.id)?'checked':''}>${esc(revText('N047',s.values.N047))}</label>`).join('')}</fieldset>`).join('');
 }else if(q.type==='日期区间'){input=`<div class="row"><label>开始月份<input type="month" ${attr} data-part="start" value="${esc(v?.start||'')}"></label><label>结束月份（留空为至今）<input type="month" ${attr} data-part="end" value="${esc(v?.end||'')}"></label></div>`;
 }else if(q.type==='非负整数'){input=`<input type="number" min="0" step="1" ${attr} value="${esc(v??'')}" placeholder="未统计留空；无则填0">`;
 }else input=q.type.includes('多行')?`<textarea ${attr}>${esc(v||'')}</textarea>`:`<input ${attr} value="${esc(v||'')}">`;
 return `<div class="field"><label>${esc(q.label)} <span class="optional">${q.id} · ${esc(q.required)}</span></label><small>${esc(q.hint)}</small>${input}<div class="error" id="err-${key.replace('|','-')}"></div></div>`;
}
function revErrors(q,v){const text=revText(q.id,v);if(q.required==='必填'&&!text.trim())return '请填写本题（可先保存草稿）。';if(q.type==='非负整数'&&v!==null&&v!==undefined&&v!==''&&(!Number.isInteger(Number(v))||Number(v)<0))return '请填写非负整数。';if(v?.selected?.some(k=>revOptions(q.id).find(o=>o.id===k)?.other==='是')&&!v.other?.trim())return '请补充“其他”的具体内容。';if(q.type.includes('＋')&&v?.selected?.length&&!v.note?.trim())return '请补充具体说明。';if(v?.start&&v.end&&v.start>v.end)return '结束时间不能早于开始时间。';if(q.id==='N052'&&v!==null&&v!==undefined&&v!==''&&revHas('N051')&&Number(v)>Number(revFirst('N051')))return '同一统计口径下，人数不能超过全部渠道咨询人数。';return '';}
let revMode='wizard';
function revRender(mode='wizard'){revMode=mode;const r=revInit();const step=Math.min(4,r.step||0);const categories=[...new Set(revQuestions.map(q=>q.module))];const modules=mode==='library'?(state.openGroup===0?categories:[categories[({1:0,3:0,6:1,8:2})[state.openGroup]??0]]):null;const questions=revQuestions.filter(q=>q.id!=='N078'&&(modules?modules.includes(q.module):coreIds[step].includes(q.id)));const rendered=new Set();let fields='';for(const q of questions){const g=revGroup(q.id);if(g){if(mode==='wizard'&&!(r.records[g]||[]).length)r.records[g]=[{id:crypto.randomUUID(),values:{}}];if(rendered.has(g))continue;rendered.add(g);fields+=`<section><h3>${revGroupNames[g]}</h3>${(r.records[g]||[]).map((record,i)=>`<details open><summary>${revGroupNames[g]} ${i+1}</summary>${revGroups[g].filter(id=>mode==='library'||coreIds[step].includes(id)).map(id=>revQuestions.find(x=>x.id===id)).filter(Boolean).filter(x=>!(g==='cases'&&revText('N030',record.values.N030).includes('禁止使用')&&x.id!=='N030')).map(x=>revControl(x,record)).join('')}${mode==='library'?`<button type="button" data-remove="${record.id}" data-group="${g}">删除本条</button>`:''}</details>`).join('')}${mode==='library'?`<button type="button" data-add="${g}">添加${revGroupNames[g]}</button>`:''}</section>`;}else if(revVisible(q))fields+=revControl(q);}
 app.innerHTML=`<main class="library"><button id="rev-back">${mode==='library'?'返回定位草稿':'返回首页'}</button><h1>${mode==='library'?(state.openGroup===0?'全部补充资料':modules[0]):revStages[step]}</h1><p class="small">最新67题 · 先填核心问题，再分类补充 · 自动保存草稿</p>${mode==='wizard'?`<p>主题 ${step+1} / 5</p><div class="progress"><i style="display:block;background:var(--blue);height:3px;width:${(step+1)/5*100}%"></i></div>`:''}<p class="muted">选填部分可以跳过。核心回答会带入补充区，无需重复填写。</p><form id="rev-form" novalidate>${fields}<div id="rev-error" class="error" role="alert"></div><div class="actions"><button type="button" id="rev-prev">${mode==='library'?'保存草稿':step?'上一步':'保存草稿'}</button><button type="submit" class="primary">${mode==='library'?'检查并返回':step===4?'生成定位草稿':'检查并继续'}</button></div><button type="button" class="quiet" id="rev-skip">${mode==='library'?'稍后完善，返回草稿':'暂存并进入下一阶段'}</button></form></main>`;
 const resolve=key=>{const parts=key.split('|');if(parts.length===1)return [r.values,parts[0]];const rec=Object.values(r.records).flat().find(x=>x.id===parts[0]);return [rec.values,parts[1]];};
 document.querySelectorAll('[data-rev]').forEach(el=>{const handler=()=>{const [obj,id]=resolve(el.dataset.rev),q=revQuestions.find(x=>x.id===id);if(el.dataset.opt){const opts=revOptions(id),o=opts.find(x=>x.id===el.dataset.opt),old=obj[id]||{selected:[],other:'',note:''};let selected=old.selected||[];if(q.type==='单选')selected=[o.id];else if(selected.includes(o.id))selected=selected.filter(x=>x!==o.id);else{selected=o.exclusive==='是'?[]:selected.filter(k=>opts.find(x=>x.id===k)?.exclusive!=='是');if(selected.length>=(Number(o.max)||opts.length))return toast('已达到最多可选数量');selected=[...selected,o.id];}obj[id]={...old,selected};if(!selected.some(k=>opts.find(o=>o.id===k)?.other==='是'))obj[id].other='';if(id==='N030'&&o.text.includes('禁止使用'))for(const k of revGroups.cases)if(k!==id)delete obj[k];revSync();revRender(mode);
 }else if(el.dataset.link){const [business,service]=el.dataset.link.split('|');obj[id]=(obj[id]||[]).filter(l=>l.business!==business||l.service!==service);if(el.checked)obj[id].push({business,service});revSync();}
 else{if(el.dataset.part)obj[id]={...obj[id],[el.dataset.part]:el.value};else obj[id]=q.type==='非负整数'?(el.value===''?null:Number(el.value)):el.value;revSync();const error=revErrors(q,obj[id]);document.getElementById('err-'+el.dataset.rev.replace('|','-')).textContent=error;if(id==='N051'){revRender(mode);document.querySelector('input[data-rev="N051"]')?.focus();}}};el.addEventListener(el.tagName==='BUTTON'?'click':'input',handler);});
 document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const g=b.dataset.add;r.records[g]||=[];const values={};if(g==='services'&&(r.records[g]||[]).length>=3)return toast('最多建立3项服务');r.records[g].push({id:crypto.randomUUID(),values});revSync();revRender(mode);});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{r.records[b.dataset.group]=r.records[b.dataset.group].filter(x=>x.id!==b.dataset.remove);r.values.N059=(r.values.N059||[]).filter(x=>x.business!==b.dataset.remove&&x.service!==b.dataset.remove);revSync();revRender(mode);});
 const advance=()=>{revSync();if(mode==='library')go('result');else if(step<4){r.step++;save();revRender();window.scrollTo(0,0);}else{const missing=['N001','N003','N004','N007','N043'].filter(id=>!revHas(id));if(missing.length){document.querySelector('#rev-error').textContent='草稿已保存。生成方向前请补充：'+missing.join('、');return;}makeDraft();go('result');}};
 document.querySelector('#rev-form').onsubmit=ev=>{ev.preventDefault();let errors=[];for(const q of questions.filter(revVisible)){const g=revGroup(q.id),values=g?(r.records[g]||[]).map(x=>x.values[q.id]):[r.values[q.id]];if(g&&q.required==='必填'&&!values.length)errors.push(q.label);for(const v of values)if(revErrors(q,v)||(q.required==='条件必填'&&!revText(q.id,v)))errors.push(q.label);}if(errors.length){document.querySelector('#rev-error').textContent='请检查：'+[...new Set(errors)].join('、');return;}advance();};
 document.querySelector('#rev-back').onclick=()=>go(mode==='library'?'result':'intro');document.querySelector('#rev-prev').onclick=()=>{revSync();if(mode==='wizard'&&step){r.step--;revRender();}else toast('草稿已保存');};document.querySelector('#rev-skip').onclick=advance;
}
wizard=()=>revRender('wizard');library=()=>revRender('library');
const originalResult=result;
result=()=>{originalResult();if(!state.draft)return;const section=document.createElement('section');section.className='supplement';section.innerHTML=`<h2>定位方向确认</h2><p class="small">当前提供1个基于填写内容的模板方向，不作市场有效性保证。</p><h3>${esc(state.draft.position)}</h3><p>目标客户：${esc(a().client||'待识别')}</p><p>主推服务：${esc(revLabel('N059')||revLabel('N047')||'待关联服务产品')}</p><p>推荐依据：${esc(a().priority||'尚无优先业务')}；${esc(revLabel('N025')||'专业依据待补充')}。</p><p>待验证：目标客户需求、付费意愿和实际交付能力。代表事项默认为内部资料，不自动进入公开内容。</p><div class="choices"><button data-direction="accept">愿意先验证这个方向</button><button data-direction="adjust">都不合适，重新调整</button><button data-direction="later">暂不决定</button></div><p id="direction-status">${esc(state.directionDecision||'尚未选择')}</p>`;document.querySelector('.result').append(section);section.querySelectorAll('button').forEach(b=>b.onclick=()=>{state.directionDecision={accept:'愿意先验证',adjust:'需要重新调整',later:'暂不决定'}[b.dataset.direction];save();if(b.dataset.direction==='adjust'){revInit().step=2;go('wizard');}else section.querySelector('#direction-status').textContent=state.directionDecision;});};
const oldDownload=download;
download=()=>{if(!state.revision)return oldDownload();const data={version:3,example:!!state.demo,exportedAt:new Date().toISOString(),revision:state.revision,previousRevision:state.previousRevision,legacy:state.legacyBackup,draft:state.draft,directionDecision:state.directionDecision};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='律见-修订版填写资料.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

const originalDemo67=document.querySelector('#demo').onclick;
document.querySelector('#demo').onclick=()=>{originalDemo67();const legacy=structuredClone(state.extra);const r=revInit();for(const g of Object.keys(revGroups))r.records[g]=[{id:crypto.randomUUID(),values:{}}];const set=(id,v)=>{const g=revGroup(id);(g?r.records[g][0].values:r.values)[id]=v;};for(const q of revQuestions){if(q.id==='N078'||q.type==='关联选择')continue;const options=revOptions(q.id),old=legacy[q.id]||'';if(options.length){const selected=options.filter(o=>old.split(/[；\n]/).includes(o.text)).map(o=>o.id);set(q.id,{selected,note:q.type.includes('＋')?'虚构示例：围绕离职协商的客户需求与沟通场景。':''});}else if(q.type==='非负整数'){const match=old.match(/^\d+/);set(q.id,match?Number(match[0]):null);}else if(q.type==='日期区间')set(q.id,{start:'2014-01',end:'2018-01'});else if(old)set(q.id,old);}
const picks={N007:[0],N007A:[3],N009:[4],N012:[1,2],N012A:[0],N024:[0,4,6],N038:[0,5],N041:[1],N046:[4,6],N046A:[1,4],N054:[2],N055:[1,6,7],N056:[1],N057:[0],N061:[0,1],N063:[0,3],N064:[0,1],N064A:[0,2],N071:[2],N071A:[2],N071B:[2]};for(const [id,ix]of Object.entries(picks))set(id,{selected:ix.map(i=>revOptions(id)[i].id),note:revQuestions.find(q=>q.id===id).type.includes('＋')?'虚构示例：参考人力资源工作经历与离职协商材料整理过程，尚需验证。':''});
set('N004',8);set('N036','离职协商与劳动争议');set('N047','离职方案咨询（60分钟）');set('N049','800元/次（虚构演示价格）');set('N050',8);set('N051',30);set('N052',18);set('N053',10);set('N059',[{business:r.records.priority[0].id,service:r.records.services[0].id}]);r.step=0;revSync();render();};
document.querySelector("#export").onclick=()=>download();render();
